/** @odoo-module **/
/* ERP Heritage - Dashboard Builder
 * Original-SVG world choropleth: countries filled by a measure value. No
 * amCharts, no CDN, no vendor geodata bundle - the geometry is a pre-projected
 * asset generated by tools/gen_world_geo.py. This is the capability the
 * incumbent only fakes (they plot partner PINS over a grey backdrop): here the
 * country itself is coloured by the number.
 *
 * Graceful degrade lives in one component: when the group-by is not a country
 * field, or the geometry asset is missing, or no ISO codes resolve, it renders
 * a ranked coloured bar list from the same payload - always a useful visual,
 * never an empty map. */

import { uiText } from "../ui_text";

import { _t } from "@web/core/l10n/translation";

import { Component } from "@odoo/owl";
import { formatValue } from "./svg_util";
import { showTooltip, moveTooltip, hideTooltip } from "./tooltip";
import { WORLD_GEO, WORLD_NAMES } from "./world_geo";

const VW = 1000;
const VH = 500;
// Sequential mint ramp: light (low) -> deep (high). Interpolated in RGB.
const RAMP_LO = [230, 245, 238];
const RAMP_HI = [11, 122, 79];
const NO_DATA = "var(--eh-board-border, #dfe4e2)";

function lerpColor(t) {
    const c = RAMP_LO.map((lo, i) => Math.round(lo + (RAMP_HI[i] - lo) * t));
    return `rgb(${c[0]},${c[1]},${c[2]})`;
}

export class MapChart extends Component {
    static template = "eh_board.MapChart";
    uiText = uiText;
    static props = {
        payload: Object,
        meta: { type: Object, optional: true },
        onDrill: { type: Function, optional: true },
    };

    get viewBox() { return `0 0 ${VW} ${VH}`; }
    get fmt() {
        const p = this.props.payload;
        return (v) => formatValue(v, p.number_format, p.currency, p.unit || "");
    }

    get regions() { return this.props.payload.regions || []; }

    /** code -> {value, name, index}. */
    get valueByCode() {
        const map = {};
        for (const r of this.regions) {
            if (r.code) {
                map[String(r.code).toUpperCase()] = {
                    value: r.value || 0, name: r.name, index: r.index };
            }
        }
        return map;
    }

    get extent() {
        // Scale over only the countries that actually render on the map. A value
        // for a country absent from the bundled geometry must not stretch the
        // colour scale (which would flatten every plotted country toward one end)
        // - it is reported separately via `unmapped` instead.
        let min = Infinity, max = -Infinity;
        for (const r of this.regions) {
            const code = r.code && String(r.code).toUpperCase();
            if (!code || !(code in (WORLD_GEO || {}))) continue;
            const v = r.value || 0;
            if (v < min) min = v;
            if (v > max) max = v;
        }
        if (!isFinite(min)) { min = 0; max = 0; }
        return { min, max };
    }

    /** Countries with data that have no outline in the bundled geometry, so they
     *  cannot be drawn. Surfaced as a note rather than silently dropped. */
    get unmapped() {
        return this.regions.filter((r) => {
            const code = r.code && String(r.code).toUpperCase();
            return !code || !(code in (WORLD_GEO || {}));
        }).map((r) => ({ name: r.name || r.code, value: this.fmt(r.value || 0) }));
    }

    /** The choropleth only renders when the geometry loaded, the server did not
     *  flag degrade, and at least one region code matches a country outline. */
    get canMap() {
        if (this.props.payload.degrade) return false;
        if (!WORLD_GEO || !Object.keys(WORLD_GEO).length) return false;
        const codes = this.valueByCode;
        return Object.keys(WORLD_GEO).some((c) => c in codes);
    }

    colorFor(value) {
        const { min, max } = this.extent;
        if (max <= min) return lerpColor(value > 0 ? 0.75 : 0.25);
        return lerpColor((value - min) / (max - min));
    }

    /** One entry per country outline; matched countries carry the value fill. */
    get shapes() {
        const codes = this.valueByCode;
        const out = [];
        for (const code of Object.keys(WORLD_GEO)) {
            const hit = codes[code];
            out.push({
                code,
                d: WORLD_GEO[code],
                name: (hit && hit.name) || WORLD_NAMES[code] || code,
                value: hit ? hit.value : null,
                index: hit ? hit.index : null,
                fill: hit ? this.colorFor(hit.value) : NO_DATA,
                hasData: !!hit,
            });
        }
        return out;
    }

    /** Legend gradient stops + the min/max labels. */
    get legend() {
        const { min, max } = this.extent;
        const stops = [0, 0.25, 0.5, 0.75, 1].map((t) => ({
            offset: `${t * 100}%`, color: lerpColor(t),
        }));
        return { stops, min: this.fmt(min), max: this.fmt(max) };
    }

    // -- fallback: ranked coloured bars (non-country dim / no geometry) ------
    get fallbackBars() {
        const labels = this.props.payload.labels || [];
        const series = (this.props.payload.series || [])[0];
        const data = series ? series.data : [];
        const rows = labels.map((label, i) => ({ label, value: data[i] || 0, index: i }));
        rows.sort((a, b) => b.value - a.value);
        const max = Math.max(1, ...rows.map((r) => Math.abs(r.value)));
        const min = Math.min(0, ...rows.map((r) => r.value));
        const span = (max - min) || 1;
        return rows.slice(0, 30).map((r) => ({
            ...r,
            width: `${Math.max(2, (Math.abs(r.value) / max) * 100)}%`,
            color: lerpColor((r.value - min) / span),
            display: this.fmt(r.value),
        }));
    }

    // -- interaction --------------------------------------------------------
    onRegionClick(shape) {
        // Drill / cross-filter through the row index so the country many2one is
        // scoped correctly (the same path every other chart uses).
        if (shape.hasData && shape.index != null && this.props.onDrill) {
            this.props.onDrill({ label: shape.name, index: shape.index });
        }
    }
    onRegionHover(ev, shape) {
        const val = shape.hasData ? this.fmt(shape.value) : _t("No data");
        showTooltip(ev, shape.name, [{ label: _t("Value"), value: val, color: shape.fill }]);
    }
    onBarClick(bar) {
        if (this.props.onDrill) this.props.onDrill({ label: bar.label, index: bar.index });
    }
    onBarHover(ev, bar) {
        showTooltip(ev, bar.label, [{ label: _t("Value"), value: bar.display, color: bar.color }]);
    }
    onMove(ev) { moveTooltip(ev); }
    onLeave() { hideTooltip(); }
}
